using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 Vector3 SettlementMissionPoint(SurvivorSettlement t){if(t.QuestZ==0){double x=t.X+68,z=t.Z+75;for(int a=0;a<80&&!OutdoorFree(x,z);a++){x=t.X+(a%2==0?1:-1)*(45+a%8*6);z=t.Z+45+a/8*5;}t.QuestX=x;t.QuestZ=z;}return Ground(t.QuestX,t.QuestZ);}
 bool SettlementMissionActive(int i)=>i==3?Ledger.State=="debt"&&!Ledger.CacheTaken:Town(i).StoryStage==1&&!Town(i).Fallen;
 void SpawnSettlementSites(){if(!LivingEnabled||dungeon!=null)return;foreach(var t in game.World.Changes.Settlements){string id="settlement/site/"+t.Index;var existing=props.FirstOrDefault(p=>p.Id==id);if(existing!=null){existing.Node.Visible=SettlementMissionActive(t.Index);continue;}if(!SettlementMissionActive(t.Index))continue;var point=SettlementMissionPoint(t);if(!NearActiveSurface(point,160)||!uniqueObjects.Add(id))continue;var root=new Node3D{Name="MissingSupplyRun",Position=point};worldRoot.AddChild(root);props.Add(new(){Id=id,Kind=34,Material=t.Index,Position=point,Node=root});Box(root,new(0,.2f,0),new(2,.4f,2),Wood);Box(root,new(1.8f,.5f,-1),new(.7f,1,.7f),Steel,true);if(t.Index<3){var person=new Node3D{RotationDegrees=new(0,0,65),Position=new(0,.1f,0)};root.AddChild(person);HumanCharacter(person,1,0,true);}else{Box(root,new(0,.6f,0),new(1.4f,.6f,1.3f),Steel,true);StoryPaper(root,new(0,.94f,0));}root.AddChild(new Label3D{Text=t.Index==3?"SEIZED SHIPMENT / BLACK LEDGER":"WOUNDED / "+ScoutName(t.Index),Position=new(0,2.4f,0),FontSize=22,PixelSize=.005f,Billboard=BaseMaterial3D.BillboardModeEnum.Enabled});}
  if(CoopClient)return;foreach(var t in game.World.Changes.Settlements.Where(t=>SettlementMissionActive(t.Index))){var point=SettlementMissionPoint(t);if(!NearActiveSurface(point,90))continue;for(int j=0;j<2+t.Index;j++){if((t.MissionKills&(1<<j))!=0)continue;var at=point+new Vector3(Mathf.Sin(j*2.4f)*7,0,Mathf.Cos(j*2.4f)*7);AddEnemy($"settlement-mission/{t.Index}/{j}/{game.Save.Seed}",at.X,at.Z,Math.Min(4,t.Index+2));}}
  if(Ledger.State is "assault" or "burning")SpawnSettlementCombatants(Ledger.Target);if(Ledger.State=="enemy")SpawnSettlementCombatants(3);
 }
 WorldProp NearSettlementSite()=>!LivingEnabled||dungeon!=null?null:props.Where(p=>p.Kind==34&&SettlementMissionActive(p.Material)&&Distance(p.Position,player.Position)<3.5f||p.Kind==35&&Ledger.State=="infiltration"&&Distance(p.Position,player.Position)<3.5f).OrderBy(p=>Distance(p.Position,player.Position)).FirstOrDefault();
 string SettlementSitePrompt(){var p=NearSettlementSite();return p==null?"":p.Kind==35?"F / SABOTAGE "+(p.Material==0?"WATER":p.Material==1?"GATE RADIO":"FUEL STORES / LETHAL BETRAYAL"):p.Material==3?"F / RECOVER SEIZED SHIPMENT":"F / SAVE "+ScoutName(p.Material)+" / 1 BANDAGE";}
 bool SettlementSiteInteract(){var p=NearSettlementSite();if(p==null)return false;string op=p.Kind==35?"sabotage:"+p.Material:"rescue:"+p.Material;if(!CoopRequest("settlement-site",op))SettlementSiteAction(op);return true;}
 void SettlementSiteAction(string data){if(CoopClient||!LivingEnabled)return;var p=NearSettlementSite();if(p==null)return;string expected=p.Kind==35?"sabotage:"+p.Material:"rescue:"+p.Material;if(data!=expected)return;
  if(p.Kind==34){var t=Town(p.Material);if(Enumerable.Range(0,2+t.Index).Any(j=>(t.MissionKills&(1<<j))==0)){game.Notice="Clear the infected around the supply run first.";return;}if(t.Index==3){Ledger.CacheTaken=true;game.Notice="Shipment recovered. The manifest lists confiscated survivor rations. Return to Voss.";}else{if(game.Life.Bandages<1){game.Notice="The survivor needs one bandage.";return;}game.Life.Bandages--;t.RescuedScout=true;AdvanceSettlement(t,2,1,ScoutName(t.Index)+" made it home alive. The recovered supplies can support a real rebuilding project.");RememberTown(t.Index,12,t.StoryResult);game.Notice=t.StoryResult;}p.Node.Visible=false;
  }else{if(p.Material==0){if(Ledger.WaterSabotaged)return;Ledger.WaterSabotaged=true;RememberTown(Ledger.Target,-15,"You contaminated the water we trusted you to protect.");game.Notice="The tank is contaminated. You can still expose the order before lighting the stores.";}else if(p.Material==1){Ledger.GateSabotaged=true;game.Notice="The gate radio is disabled. Their warning cannot get out.";}else{if(!Ledger.WaterSabotaged||!Ledger.GateSabotaged){game.Notice="Disable the water and gate radio first.";return;}if(!PaySettlementCost(0,0,0,0,0,4))return;Ledger.Burning=true;Ledger.State="burning";Ledger.FireTime=0;Town(Ledger.Target).Trust=-100;RememberTown(Ledger.Target,-100,"You used our trust to burn us out.");game.Notice="The stores ignite. The residents discover your betrayal. There is no undoing this.";}}
  game.Persist();FeverSync();
 }
 void DressSettlement(Node3D root,SurvivorSettlement t){Color accent=t.Index==0?new(.35f,.52f,.25f):t.Index==1?new(.73f,.48f,.18f):t.Index==2?new(.73f,.78f,.73f):new(.48f,.10f,.09f);Box(root,new(-8,2,0),new(2.5f,1.1f,.15f),accent);root.AddChild(new Label3D{Text=ExpeditionGame.SettlementNames[t.Index].ToUpperInvariant(),Position=new(-8,2,-.15f),FontSize=25,PixelSize=.005f});
  if(t.Index==0){for(int j=0;j<6;j++){Box(root,new(-8+j*2,.1f,8),new(1.5f,.2f,3),new(.22f,.16f,.10f));for(int k=0;k<3;k++)Ellipsoid(root,new(-8+j*2,.35f,7+k),new(.35f,.3f,.3f),accent);}}
  if(t.Index==1){for(int j=0;j<3;j++){Box(root,new(-9+j*3,.65f,7),new(2,1.3f,3),Steel,true);Tube(root,new(-10+j*3,1.5f,6),new(-8+j*3,1.5f,6),.09f,Wood);}Box(root,new(7,.8f,7),new(4,.2f,1.5f),Steel,true);}
  if(t.Index==2){for(int j=0;j<3;j++){FamilyBed(root,new(-8+j*3,0,8));Box(root,new(-8+j*3,2.1f,8),new(2.7f,.15f,3),accent,true);}Box(root,new(8,1.5f,5),new(.2f,1.2f,.1f),new(.65f,.12f,.10f));Box(root,new(8,1.5f,5),new(.8f,.2f,.12f),new(.65f,.12f,.10f));}
  if(t.Index==3){for(int j=-1;j<=1;j+=2){Box(root,new(j*11,1.5f,0),new(1,3,20),Steel,true);if(j<0)Box(root,new(0,1.5f,-10),new(20,3,1),Steel,true);else foreach(int side in new[]{-1,1})Box(root,new(side*7,1.5f,10),new(6,3,1),Steel,true);}Box(root,new(0,1.4f,10),new(4,2.8f,1.1f),Wood);for(int j=0;j<3;j++)Box(root,new(-6+j*6,3,-8),new(1.2f,2,.1f),accent);}
 }
 void DrawSettlementGrowth(Node3D root,SurvivorSettlement t){var growth=root.GetNodeOrNull<Node3D>("Growth");string version=$"{t.Development}/{t.Foundation}/{t.Policy}/{t.DeadResidents}/{t.Destroyed}/{Ledger.Target}/{Ledger.Route}/{Ledger.Burning}";if(growth!=null&&growth.GetMeta("revision").AsString()==version)return;if(growth!=null){root.RemoveChild(growth);growth.QueueFree();}growth=new Node3D{Name="Growth"};growth.SetMeta("revision",version);root.AddChild(growth);
  if(t.Development>=1){Box(growth,new(-5,.8f,5),new(3,.2f,1.5f),Wood,true);for(int j=0;j<t.Development;j++)Box(growth,new(-6+j,.99f,5),new(.6f,.4f,.6f),Steel);}
  if(t.Development>=2){Box(growth,new(7,2.8f,0),new(5,.15f,6),t.Foundation=="care"?Cloth:Steel,true);if(t.Foundation=="fortify")for(int j=0;j<4;j++)Box(growth,new(-9+j*6,1,10),new(3,2,.4f),Wood,true);else for(int j=0;j<3;j++)Tube(growth,new(6+j,0,1),new(6+j,2.8f,1),.08f,Steel);}
  if(t.Development>=3)for(int j=0;j<3;j++){Box(growth,new(8,1,4+j*1.6f),new(2,2,1.2f),Wood,true);Ellipsoid(growth,new(7,2.6f,4+j*1.6f),new(.12f,.12f,.12f),new(1,.73f,.28f));}
  for(int j=0;j<4;j++)if((t.DeadResidents&(1<<j))!=0){Box(growth,new(-9+j*1.7f,.4f,-10),new(.13f,.8f,.12f),Wood);Box(growth,new(-9+j*1.7f,.55f,-10),new(.5f,.1f,.12f),Wood);}
  if(t.Index==Ledger.Target&&Ledger.Burning&&!t.Fallen){for(int j=0;j<4;j++){Ellipsoid(growth,new(2+j,1.2f+(j%2)*.4f,6),new(.5f,1.3f,.5f),new(1,.24f,.035f));Ellipsoid(growth,new(2+j,3,6),new(.8f,1.1f,.8f),new(.17f,.16f,.15f));}growth.AddChild(new OmniLight3D{Position=new(4,2,6),LightColor=new(1,.3f,.06f),LightEnergy=2,OmniRange=12});}if(t.Destroyed){for(int j=0;j<6;j++)Box(growth,new(-8+j*3,.5f,3),new(1.6f,1,2),new(.08f,.07f,.065f));}
  if(t.Index==Ledger.Target&&Ledger.Route=="infiltration"){foreach(int j in new[]{0,1,2}){var at=root.Position+new Vector3(j==0?6:j==1?-9:4,.3f,j==2?7:0);string id="settlement/sabotage/"+j;if(uniqueObjects.Add(id)){var n=new Node3D{Position=at};worldRoot.AddChild(n);Box(n,new(0,.5f,0),new(1,1,1),j==2?new Color(.57f,.18f,.10f):Steel,true);props.Add(new(){Id=id,Kind=35,Material=j,Position=at,Node=n});}}}
 }
}
internal partial class ExpeditionMapCanvas {
 void DrawSettlementMissions(){var ledgerTown=World.Changes.Settlements.FirstOrDefault(t=>t.Index==3);if(World.Changes.Ledger?.State=="debt"&&ledgerTown?.QuestZ!=0){var at=Map(ledgerTown.QuestX,ledgerTown.QuestZ);DrawCircle(at,5,Colors.Gold);DrawString(ThemeDB.FallbackFont,at+new Vector2(7,10),"SEIZED SHIPMENT",HorizontalAlignment.Left,-1,11,Colors.Gold);}foreach(var t in World.Changes.Settlements.Where(t=>t.StoryStage==1&&t.QuestZ!=0)){var p=Map(t.QuestX,t.QuestZ);DrawCircle(p,5,Colors.Gold);DrawString(ThemeDB.FallbackFont,p+new Vector2(7,10),"MISSING / "+MigrationScene.SettlementScoutMapName(t.Index),HorizontalAlignment.Left,-1,11,Colors.Gold);}var l=World.Changes.Ledger;if(l?.RaidScheduled==true&&!l.RaidOver&&l.RaidZ!=0){var p=Map(l.RaidX,l.RaidZ);DrawCircle(p,7,Colors.Red);DrawString(ThemeDB.FallbackFont,p+new Vector2(7,10),"LEDGER RETALIATION",HorizontalAlignment.Left,-1,11,Colors.Red);}}
}
public partial class MigrationScene {internal static string SettlementScoutMapName(int i)=>i==0?"TESSA":i==1?"RAFI":"ELI";}
